lemma unprovable_iff! [HasAxiomAndInst ��] [HasAxiomAndElim ��] [HasAxiomImply₁ ��] [HasAxiomImply₂ ��] (H : �� ⊢! φ ⭤ ψ) : �� ⊬ φ ↔ �� ⊬ ψ := by
  constructor;
  . intro hp hq; have := and₂'! H ⨀ hq; contradiction;
  . intro hq hp; have := and₁'! H ⨀ hp; contradiction;

@[simp]
lemma forthback_disj_remove [HasAxiomEFQ ��] : �� ⊢! ⋁Γ ➝ φ ⋎ ⋁(Γ.remove φ) := by
  induction Γ using List.induction_with_singleton with
  | hnil => simp;
  | hsingle ψ =>
    simp;
    by_cases h: ψ = φ;
    . subst_vars; simp;
    . simp [(List.remove_singleton_of_ne h)];
  | hcons ψ Γ h ih =>
    simp_all;
    by_cases hpq : ψ = φ;
    . simp_all only [ne_eq, List.remove_cons_self]; exact or₃''! or₁! ih;
    . simp_all [(List.remove_cons_of_ne Γ hpq)];
      by_cases hqΓ : Γ.remove φ = [];
      . simp_all;
        exact or₃''! or₂! (imp_trans''! ih $ or_replace_right! efq!);
      . simp_all;
        exact or₃''! (imp_trans''! or₁! or₂!) (imp_trans''! ih (or_replace_right! or₂!));

lemma disj_allsame! [HasAxiomEFQ ��] (hd : ∀ ψ ∈ Γ, ψ = φ) : �� ⊢! ⋁Γ ➝ φ := by
  induction Γ using List.induction_with_singleton with
  | hcons ψ Δ hΔ ih =>
    simp_all;
    have ⟨hd₁, hd₂⟩ := hd; subst hd₁;
    apply provable_iff_provable.mpr;
    apply deduct_iff.mpr;
    exact or₃'''! (by simp) (weakening! (by simp) $ provable_iff_provable.mp $ ih) id!
  | _ => simp_all;

